-- Paste into the Supabase SQL editor. Every row should say true. A false row tells you which migration to run.
select
  to_regclass('public.jobs') is not null                                                         as "0007 jobs",
  exists (select 1 from information_schema.columns where table_name = 'jobs' and column_name = 'city')          as "0010 job location",
  exists (select 1 from information_schema.columns where table_name = 'competitions' and column_name = 'access') as "0011 competitions v2",
  to_regprocedure('public.competition_settle(uuid)') is not null                                 as "0012 security",
  to_regclass('public.tutor_profiles') is not null                                               as "0013 tutors",
  to_regclass('public.site_settings') is not null                                                as "0014 tutor switch",
  exists (select 1 from information_schema.columns where table_name = 'lessons' and column_name = 'font') as "0015 content tools",
  exists (select 1 from information_schema.columns where table_name = 'jobs' and column_name = 'gender_pref') as "0016 notes fixes (job gender)",
  exists (select 1 from information_schema.columns where table_name = 'questions' and column_name = 'question_type') as "0016 notes fixes (question types)",
  exists (select 1 from information_schema.columns where table_name = 'competition_winners' and column_name = 'payment_ref') as "0016 notes fixes (winner payment)",
  to_regprocedure('public.competition_leaderboard(uuid)') is not null as "0017 ranking (re-run 0017 if you had an older build)",
  to_regclass('public.question_answers') is not null as "0018A answer key setup",
  to_regprocedure('public.grade_quiz(uuid,jsonb)') is not null as "0018A grade_quiz",
  not exists (select 1 from information_schema.columns where table_name = 'question_options' and column_name = 'is_correct') as "0018B answer key locked (run AFTER v12 deploy)",
  to_regclass('public.notifications') is not null as "0019 notifications",
  not exists (select 1 from information_schema.columns where table_name = 'competitions' and column_name = 'quiz_id') as "0020 cleanup",
  exists (select 1 from information_schema.columns where table_name = 'competitions' and column_name = 'course_id') as "0021 course competitions",
  to_regprocedure('public.competition_course_eligible(uuid)') is not null as "0021 eligibility fn",
  exists (select 1 from information_schema.columns where table_name = 'users' and column_name = 'telegram_username') as "0021 profile extras",
  to_regclass('public.job_contacts') is not null as "0022 job contacts locked",
  not exists (select 1 from information_schema.columns where table_name = 'jobs' and column_name = 'contact_phone') as "0022 phone off public jobs",
  to_regprocedure('private.sx_notify(uuid,text,text,text,text)') is not null as "0022 notify helper private",
  to_regprocedure('public.competition_replace_winner(uuid,int)') is not null as "0023 prize rebuild",
  to_regclass('public.competition_removed_winners') is not null as "0023 removed winners tracked",
  exists (select 1 from pg_policies where schemaname = 'public' and tablename = 'lessons' and policyname = 'admin insert any lesson') as "0024 admin lesson insert",
  to_regclass('public.competition_winner_removals') is not null as "0025 winner removals log",
  to_regprocedure('private.competition_rebuild_winners(uuid,uuid,uuid,text,boolean)') is not null as "0025 paid protection",
  to_regprocedure('public.competition_remove_paid_winner(uuid,uuid,text)') is not null as "0025 paid removal fn",
  exists (select 1 from information_schema.columns where table_name = 'lessons' and column_name = 'visibility') as "0026 lesson visibility column",
  exists (select 1 from pg_constraint where conname = 'lessons_visibility_check') as "0026 visibility values checked",
  to_regprocedure('public.lesson_member_access(uuid)') is not null as "0026 member access fn",
  exists (select 1 from pg_policies where schemaname = 'public' and tablename = 'quizzes' and policyname = 'read quizzes of visible lessons') as "0026 quiz follows lesson",
  public.probe_private_lessons_hidden() as "0026 private lessons hidden (behaviour probe)",
  pg_get_functiondef('public.grade_quiz(uuid,jsonb)'::regprocedure) like '%lesson_not_accessible%' as "0027 quiz gate in grade_quiz",
  not has_function_privilege('authenticated', 'public.probe_private_lessons_hidden()', 'execute') as "0027 probe locked";
